/**
 * The time unit used to specify how often a recurring event occurs.
 * @export
 * @enum {string}
 */

export const CalendarEventFrequency = {
    Daily: 'daily',
    Monthly: 'monthly',
    Weekly: 'weekly',
    Yearly: 'yearly'
} as const;

export type CalendarEventFrequency = typeof CalendarEventFrequency[keyof typeof CalendarEventFrequency];


/**
 * How an event occurs or recurs. \"single\" is a standalone event, \"series\" is a parent specification of a recurring series, and \"occurrence\" is an individual event in a series.
 * @export
 * @enum {string}
 */

export const CalendarEventOccurrenceKind = {
    Occurrence: 'occurrence',
    Series: 'series',
    Single: 'single'
} as const;

export type CalendarEventOccurrenceKind = typeof CalendarEventOccurrenceKind[keyof typeof CalendarEventOccurrenceKind];


/**
 * 
 * @export
 * @enum {string}
 */

export const CalendarEventPlatform = {
    Android: 'android',
    Ios: 'ios',
    Standalonewindows: 'standalonewindows'
} as const;

export type CalendarEventPlatform = typeof CalendarEventPlatform[keyof typeof CalendarEventPlatform];


/**
 * Details about how a recurring event will be scheduled. If the event is to be scheduled indefinitely, this will lack an \"end\" property.
 * @export
 * @interface CalendarEventRecurrence
 */
export interface CalendarEventRecurrence {
    /**
     * Which days of the week the event will be scheduled, only valid/present for \"weekly\" recurring events
     * @type {Array<CalendarDayOfWeek>}
     * @memberof CalendarEventRecurrence
     */
    'daysOfWeek'?: Array<CalendarDayOfWeek>;
    /**
     * 
     * @type {CalendarEventRecurrenceEnd}
     * @memberof CalendarEventRecurrence
     */
    'end'?: CalendarEventRecurrenceEnd;
    /**
     * 
     * @type {CalendarEventFrequency}
     * @memberof CalendarEventRecurrence
     */
    'frequency': CalendarEventFrequency;
    /**
     * How often the event will be scheduled, in units of \"frequency\"
     * @type {number}
     * @memberof CalendarEventRecurrence
     */
    'interval': number;
    /**
     * The timezone the event will be scheduled in, in Area/Location format
     * @type {string}
     * @memberof CalendarEventRecurrence
     */
    'timezone': string;
}


/**
 * Details about how a recurring event stops being scheduled
 * @export
 * @interface CalendarEventRecurrenceEnd
 */
export interface CalendarEventRecurrenceEnd {
    /**
     * Required for \"afterOccurrences\" - The number of times the event will be scheduled before it stops being scheduled
     * @type {number}
     * @memberof CalendarEventRecurrenceEnd
     */
    'count'?: number;
    /**
     * Required for \"afterDate\" - The date and time after which the event will stop being scheduled, **without timezone or offset**
     * @type {string}
     * @memberof CalendarEventRecurrenceEnd
     */
    'date'?: string;
    /**
     * 
     * @type {CalendarEventRecurrenceEndType}
     * @memberof CalendarEventRecurrenceEnd
     */
    'type': CalendarEventRecurrenceEndType;
}


/**
 * How a recurring event stops being scheduled
 * @export
 * @enum {string}
 */

export const CalendarEventRecurrenceEndType = {
    AfterDate: 'afterDate',
    AfterOccurrences: 'afterOccurrences'
} as const;

export type CalendarEventRecurrenceEndType = typeof CalendarEventRecurrenceEndType[keyof typeof CalendarEventRecurrenceEndType];


